output_text:
[
  {
    "id": "no_cart_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles, identified by a one-cell horizontal width with shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "no_push_cart_into_single_file",
    "text": "A shopper must not push a cart from an open aisle into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "cart_enters_single_file": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE",
              {
                "not": "single_file_shelf_aisle"
              }
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_enters_single_file"
    }
  },
  {
    "id": "park_before_upper_pick_aisle",
    "text": "At the wide mouth of an upper single-file picking aisle, shoppers may not move north into the aisle while still holding the cart.",
    "abstraction": {
      "state_properties": {
        "wide_transverse_aisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "upper_pick_aisle_mouth": {
          "and": [
            "wide_transverse_aisle",
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "upper_pick_aisle_mouth",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "drop_cart_only_at_parking_places",
    "text": "A cart may only be parked by interacting at the entrance cart bay or at a wide aisle mouth used for single-file shelf access.",
    "abstraction": {
      "state_properties": {
        "wide_transverse_aisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "upper_pick_aisle_mouth": {
          "and": [
            "wide_transverse_aisle",
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        },
        "entrance_cart_bay": "at(1,7)",
        "approved_cart_parking_place": {
          "or": [
            "entrance_cart_bay",
            "upper_pick_aisle_mouth"
          ]
        }
      },
      "events": {
        "drop_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "drop_cart",
          {
            "not": "approved_cart_parking_place"
          }
        ]
      }
    }
  },
  {
    "id": "reclaim_cart_from_aisle_mouth",
    "text": "Whenever a shopper parks a cart at a single-file aisle mouth, they are obliged to reclaim it before leaving.",
    "abstraction": {
      "state_properties": {
        "upper_pick_aisle_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cart_dropped_at_mouth": {
          "pre": {
            "and": [
              "upper_pick_aisle_mouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cart_picked_up_at_mouth": {
          "pre": {
            "and": [
              "upper_pick_aisle_mouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_dropped_at_mouth",
      "discharge": "cart_picked_up_at_mouth"
    }
  },
  {
    "id": "no_cartless_roaming_outside_allowed_zone",
    "text": "A shopper without a cart may move only within the entrance/cart-bay area or within the single-file aisle excursion zone.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_area": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "upper_pick_aisle_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "no_cart_allowed_zone": {
          "or": [
            "entrance_cart_area",
            "single_file_shelf_aisle",
            "upper_pick_aisle_mouth"
          ]
        }
      },
      "events": {
        "cartless_move_out_of_allowed_zone": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": {
            "not": "no_cart_allowed_zone"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_move_out_of_allowed_zone"
    }
  },
  {
    "id": "open_shelf_interactions_need_cart",
    "text": "Shelf interactions in open or ordinary aisles should be done with a cart; cartless shelf picking is allowed only in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "open_shelf_area": {
          "and": [
            "adjShelf",
            {
              "not": "single_file_shelf_aisle"
            }
          ]
        }
      },
      "events": {
        "shelf_interaction": {
          "pre": {
            "and": [
              "INTERACT",
              "adjShelf"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelf_interaction",
          "open_shelf_area",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "return_from_single_file_excursion",
    "text": "After entering a single-file shelf aisle on foot, a shopper is obliged to return to the wide aisle mouth before continuing.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "upper_pick_aisle_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "enter_single_file_on_foot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE",
              {
                "not": "single_file_shelf_aisle"
              }
            ]
          },
          "post": "single_file_shelf_aisle"
        },
        "return_to_mouth_on_foot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE",
              "single_file_shelf_aisle"
            ]
          },
          "post": "upper_pick_aisle_mouth"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enter_single_file_on_foot",
      "discharge": "return_to_mouth_on_foot"
    }
  }
]
